using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AbyssalShatterPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Cellarius/AbyssalShatterPreviewDescription", order = 0)]
public class AbyssalShatterPreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		return (battleAction as AbyssalShatterAction).GetPurificationAmount(GetAmountWithoutEquation(amountModified));
	}
}
